  var GIB = 1073741824;     // memory is sold in GiB: a "24 GB" card holds 24 × 2^30 bytes
  var DEFAULT_OVERHEAD_GIB = 1.0;

  /**
   * KV cache in BYTES for one model at a context, split by kind. Models carry
   * KV ELEMENTS PER TOKEN already summed over their layers (K and V counted),
   * which covers every attention layout in one formula:
   *   kvElemFull : layers whose cache grows with the whole context
   *                (for MLA: layers × (kv_lora_rank + rope dims), no K/V pair)
   *   kvElemSwa  : sliding-window / chunked layers; capped at the window only
   *                when the engine stores just the window (swaWindowOnly === true;
   *                null = undocumented, costed as full context to stay conservative).
   *                llama.cpp pads that cache by one micro-batch (swaPadTokens).
   *   stateElems : fixed recurrent state (Mamba, Gated DeltaNet) per sequence,
   *                in the model's state dtype, independent of context and KV dtype.
   * o = { kvBytes, context, parallel, engine }
   */
  function kvCache(model, o) {
    var ctx = Math.max(0, o.context), par = Math.max(1, o.parallel || 1), eng = o.engine || {};
    var full = model.kvElemFull * o.kvBytes * ctx;
    var swa = 0;
    if (model.kvElemSwa) {
      var swaCtx = (eng.swaWindowOnly === true && model.swaWindow)
        ? Math.min(ctx, model.swaWindow + (eng.swaPadTokens || 0)) : ctx;
      swa = model.kvElemSwa * o.kvBytes * swaCtx;
    }
    var state = (model.stateElems || 0) * (model.stateBytes || 2);
    return { full: full * par, swa: swa * par, state: state * par, total: (full + swa + state) * par };
  }

  function overheadOf(engine) {
    return (engine && typeof engine.overheadGiB === 'number') ? engine.overheadGiB : DEFAULT_OVERHEAD_GIB;
  }

